{
  parse(argc, argv);
  ZuTestMain();
  ZuTestCall(binaryEnvelope);
  ZuTestCall(signatureBoundary);
  ZuTestCall(growing);
  ZuTestCall(progress);
  ZuTestCall(fields);
  ZuTestCall(subIds);
  ZuTestCall(typed);
  ZuTestCall(output);
  ZuTestCall(capacity);
  ZuTestCall(splits);
  ZuTestCall(coalesced);
  ZuTestCall(corrupt);
  ZuTestCall(limits);
  return 0;
}
